async function runBrowserCli(args: string[], dependencies: BrowserCliDependencies): Promise<number> {
  const flags = parseBrowserFlags(args);
  const write = dependencies.stdout ?? ((value: string) => process.stdout.write(value));
  const anvilHome = resolve(dependencies.anvilHome ?? join(dependencies.homeDir ?? homedir(), ".anvil"));
  const command = flags._[0];
  if (!command || command === "help") {
    write(`${browserCliUsage()}\n`);
    return 0;
  }
  if (command === "install") {
    output(await installCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  if (command === "status" && flags._.length === 1) {
    output(await readCapabilityStatus(anvilHome, dependencies.anvilCommand, dependencies), flags.json, write);
    return 0;
  }
  if (command === "doctor" && flags._.length === 1) {
    const result = await doctorCommand(dependencies, anvilHome);
    output(result, flags.json, write);
    return (result as { ok: boolean }).ok ? 0 : 1;
  }
  if (command === "mcp" && flags._[1] === "serve" && flags._.length === 2) {
    return (dependencies.serveMcp ?? serveBrowserMcp)({ mode: browserMode(flags.networkMode), anvilHome });
  }
  if (command === "upgrade") {
    output(await upgradeCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  if (command === "uninstall") {
    output(await uninstallCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  throw cliError(browserCliUsage());
}

type BrowserCliDependencies = {
  anvilCommand: string;
  anvilHome?: string;
  homeDir?: string;
  stdout?: (value: string) => void;
  run?: BrowserCommandRunner;
  assertCanonical?: (anvilCommand: string, run: BrowserCommandRunner) => Promise<void>;
  buildImage?: (input: {
    installedCa: InstalledCorporateCa;
    anvilHome: string;
    baseImage?: string;
    run: BrowserCommandRunner;
  }) => Promise<CorporateImageBuildOutput>;
  reconcile?: Reconcile;
  readStatus?: ReadStatus;
  removeRenderer?: RemoveRenderer;
  installRegistrations?: typeof installCodexBrowserRegistrations;
  validateRegistrations?: typeof validateCodexBrowserRegistrations;
  registrationStatus?: typeof readCodexBrowserRegistrationStatus;
  uninstallRegistrations?: typeof uninstallCodexBrowserRegistrations;
  serveMcp?: typeof serveBrowserMcp;
};

async function main(): Promise<void> {
  if (command.length === 0 || command[0] === "--help" || command[0] === "help") {
    process.stdout.write(`${usage()}\n`);
    return;
  }

  if (command[0] === "manifest") {
    const { runManifestCli } = await import("./manifest.ts");
    await runManifestCli(command.slice(1));
    return;
  }

  if (
    command[0] === "codex" &&
    (command[1] === "context-hook" || command[1] === "session-start-hook")
  ) {
    await runContextHook();
    return;
  }

  if (command[0] === "continuity" && command[1] === "read") {
    await continuityRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "read") {
    await workContextRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "doctor") {
    await workContextDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "doctor") {
    await continuityDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "routing-audit") {
    await continuityRoutingAudit(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "init-default") {
    await continuityInitDefault(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "log") {
    await brainLog(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "usage") {
    await brainUsage(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "metrics") {
    await brainMetrics(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "dashboard") {
    await brainDashboard(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "log") {
    await skillsLog(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "invocations") {
    await skillsInvocations(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "audit-sample") {
    await skillsAuditSample(command.slice(2));
    return;
  }

  if (command[0] === "tool-result" && command[1] === "capture") {
    await captureToolResult(command.slice(2));
    return;
  }

  if (command[0] === "browser") {
    const exitCode = await runBrowserCli(command.slice(1), {
      anvilCommand: currentFile,
      ...(process.env.ANVIL_HOME ? { anvilHome: process.env.ANVIL_HOME } : {}),
    });
    if (exitCode !== 0) process.exitCode = exitCode;
    return;
  }

  if (command[0] === "mcp" && command[1] === "serve") {
    await runAnvilMcpServer();
    return;
  }

  fail(usage());
}

